declare var React;
declare var $;
declare var ReactDOM;


const PerformanceGrid = React.createClass({
    getInitialState() {
        let origin = location.origin.replace('http://', 'ws://');
        this.socket = new WebSocket(origin);
        this.socket.addEventListener('message', this.onMessage);
        return {
            entries: []
        };
    },

    onMessage(message) {
        let entry = JSON.parse(message.data);
        if(!this.startTime) {
            this.startTime = entry.time;
        }
        this.state.entries.push(entry);
        this.setState({
            entries: this.state.entries
        });
    },

    format(value, length) {
        let ret = String(value);
        while(ret.length < length) {
            ret = "0" + ret;
        }
        return ret;
    },

    render() {
        let rows = [];
        this.state.entries.forEach((entry, i) => {

            const date = new Date(entry.time);

            const hours = this.format(date.getHours(), 2);
            const minutes = this.format(date.getMinutes(), 2);
            const seconds = this.format(date.getSeconds(), 2);
            const ms = this.format(date.getMilliseconds(), 3);

            const time = `${hours}:${minutes}:${seconds}:${ms}`;
            rows.push(<tr key={i}>
                <td className="time"><samp>{time}</samp></td>
                <td className="type"><code>{entry.type}</code></td>
                <td className="desc">{entry.description}</td>
            </tr>)
        });

        return <table className="table table-striped table-condensed">
            <thead>
                <tr>
                    <th className="time">Time</th>
                    <th className="type">Type</th>
                    <th className="desc">Description</th>
                </tr>
            </thead>
            <tbody>
                {rows}
            </tbody>
        </table>;
    }
});

$(document).ready(() => {
    ReactDOM.render(<PerformanceGrid/>, document.getElementById('grid'))
});
